#include "mainwindow.h"

#include <QApplication>
#include <QLocale>
#include <QTranslator>

#include "biginteger.h"
#include <iostream>
#include <QDebug>

int main(int argc, char *argv[])
{
    QApplication a(argc, argv);

    QTranslator translator;
    const QStringList uiLanguages = QLocale::system().uiLanguages();
    for (const QString &locale : uiLanguages) {
        const QString baseName = "PrakFiles_" + QLocale(locale).name();
        if (translator.load(":/i18n/" + baseName)) {
            a.installTranslator(&translator);
            break;
        }
    }
    MainWindow w;

    BigInteger x("");
    BigInteger y("");
    BigInteger u(12345678912345678);
    BigInteger k ("810000006560919059704444947049453244185588933248652983318227779671655451728980996598290866375775848750067343308111577988905168000175821207994571259351238529107643113567486154750");
    u = u.LeftShift(1);
    u = u.RightShift(1);
    long long t =10100;

    //qDebug() << static_cast<int>(Karacuba(x,y) == k);
    qDebug() << (x%y == k);
    qDebug() << x%BigInteger("");
    w.show();
    return a.exec();
}
